class Person {
public:
    int age;
    char name[50];
    Person(int a, const char* n) : age(a) {
        strncpy(name, n, sizeof(name) - 1);
        name[sizeof(name) - 1] = '\0';
    }
    Person() : age(0) {
        name[0] = '\0';
    }
    void greet() const {
        printf("Hello, my name is %s and I am %d years old.\n", name, age);
    }
};
int add(int a, int b) {
    return a + b;
}
